package ru.neverland.townypopulation;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import ru.neverland.core.SuiteState;
import ru.neverland.townypopulation.integration.DistrictsBridge;
import ru.neverland.townypopulation.model.DistrictCohorts;
import ru.neverland.townypopulation.service.CohortService;

/** Exact boundary, bounded demand, immutable API and no ledger lock in readers. */
public final class CohortBoundarySmoke {
    static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}static void rejected(Runnable task,String why){try{task.run();}catch(IllegalArgumentException expected){check(true,why);return;}throw new AssertionError(why);}
    static Map<String,Object> row(){var map=new HashMap<String,Object>();map.put("id","homes");map.put("name","Жилой квартал");map.put("type","RESIDENTIAL");map.put("worldAvailable",true);map.put("buildingsAvailable",true);map.put("total",4);map.put("connected",3);map.put("services",Map.of("water",Map.of("title","Вода","served",2,"total",4,"known",true)));return map;}
    static Map<String,Object> report(){return new HashMap<>(Map.of("format",2,"available",true,"pending",false,"sourceAt",90_000L,"checkedAt",91_000L,"homeKnown",true,"rows",Map.of("homes",row()),"assignments",Map.of("tavern_inn","homes")));}
    public static void main(String[] args)throws Exception{
        var source=DistrictsBridge.decode(report(),100_000);check(source.available()&&source.sourceAt()==90_000&&source.assignments().get("tavern_inn").equals("homes"),"format2 keeps exact physical assignment and original source age");check(source.districts().get("homes").connectionKnown()&&source.districts().get("homes").services().get(0).served()==2,"district connection and service coverage preserved separately");
        var changed=report();changed.put("format",1);rejected(()->DistrictsBridge.decode(changed,100_000),"old format cannot be silently interpreted as unassigned city");var fraction=report();fraction.put("format",2.1);rejected(()->DistrictsBridge.decode(fraction,100_000),"fractional integer fields never truncate");
        var assignments=report();assignments.put("assignments",Map.of("tavern_inn","missing"));rejected(()->DistrictsBridge.decode(assignments,100_000),"unknown assignment never invents a district");var forged=report();var badRow=row();badRow.put("id","elsewhere");forged.put("rows",Map.of("homes",badRow));rejected(()->DistrictsBridge.decode(forged,100_000),"row key and explicit identity must agree");
        var unavailable=DistrictsBridge.decode(Map.of("available",false,"pending",true),100_000);check(!unavailable.available()&&unavailable.pending(),"pending source remains pending and does not become empty districts");check(!DistrictsBridge.decode(report(),151_000).available(),"stale district metadata cannot be shown as freshly captured");check(!DistrictsBridge.decode(report(),89_000).available(),"future source timestamp cannot pass as current");
        var noBuildings=report();var broken=row();broken.put("buildingsAvailable",false);noBuildings.put("rows",Map.of("homes",broken));check(!DistrictsBridge.decode(noBuildings,100_000).available(),"unavailable footprints cannot remove assigned residents");
        var unknown=report();var remote=row();remote.put("worldAvailable",false);remote.put("services",Map.of("water",Map.of("title","Вода","served",0,"total",4,"known",false)));unknown.put("rows",Map.of("homes",remote));var decoded=DistrictsBridge.decode(unknown,100_000);check(!decoded.districts().get("homes").connectionKnown()&&!decoded.districts().get("homes").services().get(0).known(),"unknown world and water remain unknown rather than confirmed shortage");
        var input=new DistrictCohorts.Input(23,14,10,40,10,new BigDecimal("23.123456789"),new BigDecimal("30.000001"),new BigDecimal("1.25"),BigDecimal.ONE,Map.of("@base",new DistrictCohorts.Source("@base",10,2),"tavern_inn",new DistrictCohorts.Source("tavern_inn",30,8)),source.districts(),source.assignments());
        var output=CohortService.report(DistrictCohorts.calculate(input),110_000,90_000,false);var totals=(Map<?,?>)output.get("totals");check(totals.get("population").equals(23)&&totals.get("unemployed").equals(4)&&totals.get("foodSupply").equals("23.123456789"),"primitive report preserves all people and exact decimal units");var groups=(Map<?,?>)output.get("rows");check(groups.size()==2&&((Map<?,?>)groups.get("city")).get("plots").equals(0)&&((Map<?,?>)groups.get("district:homes")).get("district").equals(true),"city fallback is separate from real district service cells");
        var clock=new AtomicLong(1);var views=new CohortService(clock::get,error->{throw new AssertionError(error);});UUID town=UUID.randomUUID();check(Boolean.TRUE.equals(views.read(town).get("pending"))&&views.wanted().contains(town),"reader requests capture without touching Towny");views.capture(town,input,90_000,false);long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(!Boolean.TRUE.equals(views.read(town).get("available"))){if(System.nanoTime()>until)throw new AssertionError("derived view did not complete");Thread.sleep(1);views.capture(town,input,90_000,false);}check(((Map<?,?>)views.read(town).get("totals")).get("population").equals(23),"detached calculation publishes conserved primitive view");
        var executor=Executors.newSingleThreadExecutor();try(var guard=SuiteState.guard()){check(executor.submit(()->views.read(town)).get(1,TimeUnit.SECONDS).get("available").equals(true),"async report read does not wait for another thread's suite guard");}finally{executor.shutdownNow();}
        var revised=new DistrictCohorts.Input(24,14,10,40,10,input.foodSupply(),input.waterSupply(),input.foodPerResident(),input.waterPerResident(),input.sources(),input.districts(),input.assignments());views.capture(town,revised,100_000,false);check(Boolean.TRUE.equals(views.read(town).get("pending"))&&((Map<?,?>)views.read(town).get("rows")).isEmpty(),"changed totals cannot expose an old ready result as current");
        for(int i=0;i<150;i++){clock.incrementAndGet();views.watch(UUID.randomUUID());}check(views.wanted().size()==128&&!views.wanted().contains(town),"interest strictly bounded with oldest request eviction");clock.addAndGet(120_000_000_001L);check(views.wanted().isEmpty(),"unused town requests expire without scanning every town");check(Boolean.TRUE.equals(views.read(town).get("pending")),"expired capture is never served as current");views.prepareClose().toCompletableFuture().get(5,TimeUnit.SECONDS);check(!Boolean.TRUE.equals(views.read(town).get("pending"))&&!Boolean.TRUE.equals(views.read(town).get("available")),"shutdown closes disposable views without pending promise");views.awaitClosed();
        System.out.println("CohortBoundarySmoke PASS "+checks+" checks");
    }
}
